package com.theone.tv;
import android.content.*;import android.view.KeyEvent;import android.widget.ListView;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.concurrent.atomic.AtomicBoolean;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class LiveTvRemoteTest {
 @Test public void remotePlaysZapsAndFiltersCountry()throws Exception{Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();assertTrue(context.getPackageManager().hasSystemFeature("android.software.leanback"));UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());Intent intent=new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK).putExtra("tv_test_mode",true);try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(intent)){
 assertTrue(device.wait(Until.hasObject(By.textContains("THE ONE TV")),10000));scenario.onActivity(a->{ListView grid=a.findViewById(1020);grid.requestFocus();grid.setSelection(0);});device.pressDPadCenter();assertTrue(device.wait(Until.hasObject(By.text("▶ Kijk live")),5000));device.pressDPadCenter();AtomicBoolean ready=new AtomicBoolean();for(int n=0;n<40&&!ready.get();n++){scenario.onActivity(a->ready.set(a.isPlaybackReadyForTest()));Thread.sleep(250);}assertTrue("Native live player renders frame",ready.get());device.pressKeyCode(KeyEvent.KEYCODE_CHANNEL_UP);ready.set(false);for(int n=0;n<40&&!ready.get();n++){scenario.onActivity(a->ready.set(a.isPlaybackReadyForTest()));Thread.sleep(250);}assertTrue("Channel-up tunes next channel",ready.get());device.pressKeyCode(KeyEvent.KEYCODE_MEDIA_PAUSE);Thread.sleep(300);scenario.onActivity(a->ready.set(a.isPlaybackReadyForTest()));assertFalse(ready.get());device.pressKeyCode(KeyEvent.KEYCODE_MEDIA_PLAY);Thread.sleep(500);scenario.onActivity(a->ready.set(a.isPlaybackReadyForTest()));assertTrue(ready.get());device.pressBack();scenario.onActivity(a->{ListView grid=a.findViewById(1020);grid.requestFocus();grid.setSelection(0);});device.pressDPadUp();device.pressDPadRight();device.pressDPadCenter();assertTrue(device.wait(Until.hasObject(By.text("Nederland")),5000));device.pressDPadDown();device.pressDPadDown();device.pressDPadCenter();Thread.sleep(300);scenario.onActivity(a->{ListView grid=a.findViewById(1020);assertEquals(4,grid.getCount());for(int n=0;n<grid.getCount();n++)assertEquals("US",((CatalogEntry)grid.getAdapter().getItem(n)).category);});
 }}
 @Test public void onlyLiveTvCatalogAndDirectHeadersAreAllowed()throws Exception{MediaRepository repo=new MediaRepository(InstrumentationRegistry.getInstrumentation().getTargetContext());assertTrue(repo.headersForUri("https://example.org/live/1").isEmpty());try{repo.load("movies",(rows,done,count)->{});fail();}catch(java.io.IOException expected){}}
}
